    topic.paras.push(
      {text:'E. Displacement: The distance of oscillating body from the mean position at any instant of time is called its displacement (x). Displacement is measured in metres (m).',urdu:'E. ہٹاؤ: کسی بھی لمحے مرتعش جسم کا وسطی مقام سے فاصلہ اس کا ہٹاؤ (x) کہلاتا ہے۔ ہٹاؤ میٹر (m) میں ناپا جاتا ہے۔',pashto:'E. بېځایه کېدل: د وخت په هره شېبه کې د اهتزاز کوونکي جسم له منځني موقعیت څخه واټن د هغه بېځایه کېدل (x) بلل کېږي. بېځایه کېدل په مترو (m) اندازه کېږي.',lead:{text:'E. Displacement:',urdu:'E. ہٹاؤ:',pashto:'E. بېځایه کېدل:'}},
      {text:'F. Amplitude: The maximum displacement of the body from its mean position in a cycle is called amplitude (x₀). Amplitude being a length, is measured in metres (m).',urdu:'F. حیطہ: ایک چکر میں جسم کا اپنے وسطی مقام سے زیادہ سے زیادہ ہٹاؤ حیطہ (x₀) کہلاتا ہے۔ حیطہ ایک لمبائی ہے، اس لیے اسے میٹر (m) میں ناپا جاتا ہے۔',pashto:'F. لمن: په یوه دوره کې د جسم له خپل منځني موقعیت څخه تر ټولو زیات بېځایه کېدل لمن (x₀) بلل کېږي. لمن یو اوږدوالی دی او په مترو (m) اندازه کېږي.',lead:{text:'F. Amplitude:',urdu:'F. حیطہ:',pashto:'F. لمن:'}}
    );
