  const sqrtMK='<msqrt><mfrac><mi>m</mi><mi>k</mi></mfrac></msqrt>';
  const twoPi='<mn>2</mn><mi>π</mi>';
  const squareT='<msup><mi>T</mi><mn>2</mn></msup>';
