  const assignment13={id:'phys10-assignment-10.3',sourceNumber:'10.3',source:{pdf:'10thphysics1.pdf',pdfPage:13,printedPage:'8'},answerOrigin:'not supplied on this page',title:{text:'ASSIGNMENT 10.3: TIME PERIOD OF MASS SPRING SYSTEM',urdu:'مشق 10.3: کمیت اور سپرنگ کے نظام کا دورانیہ',pashto:'دنده 10.3: د کتلې او فنر د سیستم دوره'},question:{text:'A body of mass 0.2 kg is attached to a spring placed on a frictionless horizontal surface. The spring constant of spring is 4 N/m. Find the time period of oscillating mass spring system.',urdu:'0.2 kg کمیت کا ایک جسم رگڑ سے پاک افقی سطح پر رکھے ہوئے سپرنگ سے منسلک ہے۔ سپرنگ کا سپرنگ مستقل 4 N/m ہے۔ ارتعاش کرتے کمیت اور سپرنگ کے نظام کا دورانیہ معلوم کریں۔',pashto:'د 0.2 kg کتلې یو جسم له داسې فنر سره تړل شوی چې پر بې رګړه افقي سطحه پروت دی. د فنر ثابت 4 N/m دی. د اهتزاز کوونکي کتلې او فنر د سیستم دوره معلومه کړئ.'}};
