  const diffraction28={caption:{text:'Figure 10.20 - Diffraction',urdu:'شکل 10.20 - تفرق',pashto:'شکل 10.20 - تفرق'},labels:[{text:'Obstacle',urdu:'رکاوٹ',pashto:'خنډ'},{text:'Opening',urdu:'سوراخ',pashto:'پرانیسته'},{text:'Wavefront',urdu:'موج محاذ',pashto:'د څپې محاذ'},{text:'Ray',urdu:'شعاع',pashto:'شعاع'}],geometry:{smallOpening:true,largeOpening:true},svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 260" role="img" aria-labelledby="phys10-diffraction-title" style="width:100%;"><title id="phys10-diffraction-title">Diffraction through a small opening produces broad circular wavefronts; a large opening leaves the central wave nearly straight and diffracts the edges</title><rect width="560" height="260" fill="white" stroke="#a16207" stroke-width="2"/><path d="M280 3V257" stroke="#a16207" stroke-width="2"/><path d="M28 55V205M58 55V205M88 55V205M118 55V205" stroke="#166534" stroke-width="2" marker-end="url(#phys10-diff-arrow)"/><path d="M178 55V102M178 158V205" stroke="#111827" stroke-width="12"/><path d="M178 102A50 50 0 0 1 178 158M178 102A83 83 0 0 1 178 158M178 102A116 116 0 0 1 178 158" fill="none" stroke="#312e81" stroke-width="2"/><path d="M178 130L250 80M178 130H250M178 130L250 180" stroke="#be123c" stroke-width="2" marker-end="url(#phys10-diff-arrow)"/><path d="M308 55V101M308 159V205" stroke="#111827" stroke-width="12"/><path d="M350 55V205M410 55V205M470 55V205" stroke="#312e81" stroke-width="2"/><path d="M308 130L530 70M308 130H530M308 130L530 190" stroke="#be123c" stroke-width="2" marker-end="url(#phys10-diff-arrow)"/><g font-family="Arial" font-size="17"><text x="78" y="35">Obstacle</text><text x="157" y="232">Opening</text><text x="332" y="35">Obstacle</text><text x="326" y="232">Opening</text><text x="208" y="67">Wavefront</text><text x="220" y="95">Ray</text><text x="5" y="250">a</text><text x="287" y="250">b</text></g><defs><marker id="phys10-diff-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M6 3 0 0v6Z" fill="#be123c"/></marker></defs></svg>`};
