  const table11_1={title:{text:'Table 11.1 LOGARITHMIC INTENSITY LEVELS AND SOUND INTENSITY',urdu:'جدول 11.1 لوگارتھمی شدت کی سطحیں اور صوتی شدت',pashto:'جدول 11.1 د لوګارتم شدت کچې او د غږ شدت'},columns:3,rows:[['0','0','1'],['10','1','10'],['20','2','100'],['30','3','1000'],['50','5','100000'],['100','10','10000000000']]};
