  const mirrorFigureSvg=(kind,title)=>{
    const base='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 240" role="img" aria-labelledby="phys10-'+kind+'"><title>'+title+'</title><rect width="420" height="240" fill="white" stroke="#4338ca" stroke-width="2"/>';
    const axis='<path d="M20 160H400" stroke="#991b1b" stroke-width="2" stroke-dasharray="8 5"/>';
    if(kind==='concave-focal')return base+axis+'<path d="M220 55Q165 160 220 215" fill="none" stroke="#2563eb" stroke-width="8"/><circle cx="95" cy="160" r="4" fill="#111827"/><circle cx="155" cy="160" r="4" fill="#16a34a"/><circle cx="220" cy="160" r="4" fill="#dc2626"/><path d="M20 75H215M20 105H215M20 135H215M215 75L155 160M215 105L155 160M215 135L155 160" stroke="#f97316" stroke-width="2"/><g font-family="Arial" font-size="15"><text x="88" y="185">C</text><text x="150" y="185">F</text><text x="215" y="185">P</text><text x="255" y="75">Incident parallel rays</text><text x="110" y="225">f = R/2</text></g></svg>';
    if(kind==='convex-focal')return base+axis+'<path d="M200 55Q255 160 200 215" fill="none" stroke="#0ea5e9" stroke-width="8"/><circle cx="265" cy="160" r="4" fill="#16a34a"/><circle cx="200" cy="160" r="4" fill="#dc2626"/><path d="M20 75H197M20 105H197M20 135H197M197 75L105 45M197 105L110 105M197 135L105 195M197 75L265 160M197 105L265 160M197 135L265 160" stroke="#f97316" stroke-width="2"/><g font-family="Arial" font-size="15"><text x="260" y="185">F</text><text x="195" y="185">P</text><text x="75" y="225">f = −R/2; virtual focus</text></g></svg>';
    if(kind==='principal-focus')return base+'<path d="M20 120H400" stroke="#991b1b" stroke-width="2" stroke-dasharray="8 5"/><path d="M205 25Q160 120 205 215M215 25Q260 120 215 215" fill="none" stroke="#2563eb" stroke-width="7"/><circle cx="125" cy="120" r="4" fill="#dc2626"/><circle cx="295" cy="120" r="4" fill="#dc2626"/><path d="M30 55H200M30 85H200M30 155H200M200 55L125 120M200 85L125 120M200 155L125 120M220 55H390M220 85H390M220 155H390M220 55L295 120M220 85L295 120M220 155L295 120" stroke="#f97316" stroke-width="2"/><path d="M200 55L125 120M200 85L125 120M200 155L125 120M220 55L295 120M220 85L295 120M220 155L295 120" stroke="#64748b" stroke-dasharray="5 4"/><g font-family="Arial" font-size="14"><text x="160" y="232">Concave: converging focus</text><text x="266" y="232">Convex: diverging rays</text><text x="115" y="110">F</text><text x="298" y="110">F</text></g></svg>';
    return base+axis+'<path d="M265 50Q205 160 265 220" fill="none" stroke="#2563eb" stroke-width="8"/><path d="M75 105V160" stroke="#16a34a" stroke-width="7"/><path d="M75 105L260 105L145 160M75 105L145 160L260 105M75 105L105 160L260 160" fill="none" stroke="#f97316" stroke-width="3"/><circle cx="145" cy="160" r="4" fill="#16a34a"/><circle cx="205" cy="160" r="4" fill="#111827"/><circle cx="265" cy="160" r="4" fill="#dc2626"/><g font-family="Arial" font-size="15"><text x="65" y="95">Object</text><text x="137" y="185">F</text><text x="198" y="185">C</text><text x="260" y="185">P</text><text x="280" y="65">Concave mirror</text></g></svg>';
  };
  const codedMirrorFigure=(caption,captionUrdu,captionPashto,kind)=>({caption:{text:caption,urdu:captionUrdu,pashto:captionPashto},labels:[{text:'Principal axis',urdu:'محورِ اصلی',pashto:'اصلي محور'},{text:'Concave mirror',urdu:'مقعر آئینہ',pashto:'مقعره هنداره'},{text:'Convex mirror',urdu:'محدب آئینہ',pashto:'محدبه هنداره'},{text:'Centre C',urdu:'مرکز C',pashto:'مرکز C'},{text:'Focus F',urdu:'مرکزی نقطہ F',pashto:'فوکل ټکی F'},{text:'Pole P',urdu:'قطب P',pashto:'قطب P'}],svg:mirrorFigureSvg(kind,caption)});
  if(t12_1){const mirrorFigures=[codedMirrorFigure('Figure 12.4 - Focal length of concave mirror','شکل 12.4 - مقعر آئینے کا مرکزی فاصلہ','12.4 شکل - د مقعرې هندارې فوکل واټن','concave-focal'),codedMirrorFigure('Figure 12.5 - Focal length of convex mirror','شکل 12.5 - محدب آئینے کا مرکزی فاصلہ','12.5 شکل - د محدبې هندارې فوکل واټن','convex-focal'),codedMirrorFigure('Figure 12.6 - Principal focus','شکل 12.6 - مرکزی نقطہ','12.6 شکل - فوکل ټکی','principal-focus'),codedMirrorFigure('Figure 12.7 - Concave mirror ray tracing','شکل 12.7 - مقعر آئینے میں شعاعی خاکہ','12.7 شکل - په مقعره هنداره کې د وړانګو رسم','concave-ray-tracing')];for(const figure of mirrorFigures)t12_1.sourceLayoutPhysics10.push({type:'figure',record:figure});}
  const first25=t12_1.paras.length;const p25_28=[
    s('Figure 12.8 - Convex mirror ray tracing: A-ray parallel to the principal axis is reflected as if it came from a focal point. F-ray directed toward the focal point is reflected parallel to the principal axis. P-ray incident on the vertex reflects at an equal angle to the axis. C-ray along a radius is reflected back on itself.','شکل 12.8 — محدب آئینے کا شعاعی خاکہ: محورِ اصلی کے متوازی A شعاع ایسے منعکس ہوتی ہے جیسے مرکزی نقطے سے آئی ہو۔ F شعاع مرکزی نقطے کی طرف جائے تو محور کے متوازی منعکس ہوتی ہے۔ P شعاع رأس پر پڑ کر محور کے ساتھ برابر زاویے سے منعکس ہوتی ہے۔ C شعاع رداس کے ساتھ جا کر اسی راستے واپس پلٹتی ہے۔','12.8 شکل — د محدبې هندارې وړانګو رسم: له محور سره موازي A وړانګه داسې منعکسېږي لکه له فوکل ټکي راغلې وي. د F وړانګه چې فوکل ټکي ته روانه وي، له محور سره موازي منعکسېږي. پر رأس د P وړانګه له محور سره په برابره زاویه منعکسېږي. د C وړانګه د شعاع په لوري بېرته پر خپل مسیر راګرځي.'),
    s('TIP BITS — Capturing solar energy with mirrors: Parabolic mirrors are also used in one method of collecting solar energy for commercial purposes. Figure shows a long row of concave parabolic mirrors that reflect the sun’s rays to the focal point. Located at the focal point and running the length of the row is an oil-filled pipe. The focused rays of the sun heat the oil. In a solar-thermal electric plant, the heat from many such rows is used to generate steam. The steam, in turn, drives a turbine connected to an electric generator.','اہم معلومات — آئینوں سے شمسی توانائی جمع کرنا: تجارتی پیمانے پر شمسی توانائی جمع کرنے کے ایک طریقے میں قطعِ مکافی آئینے استعمال ہوتے ہیں۔ مقعر آئینوں کی لمبی قطار سورج کی شعاعیں مرکزی نقطے پر منعکس کرتی ہے۔ وہاں پوری قطار کے ساتھ تیل سے بھرا پائپ ہوتا ہے؛ مرتکز شعاعیں تیل گرم کرتی ہیں۔ شمسی حرارتی بجلی گھر میں ایسی کئی قطاروں کی حرارت بھاپ بناتی ہے، جو بجلی کے جنریٹر سے منسلک ٹربائن چلاتی ہے۔','لنډې خبرې — د هندارو په وسیله لمریزه انرژي: پارابولي هندارې د سوداګریزې لمریزې انرژۍ د راټولولو لپاره کارېږي. د مقعرو پارابولي هندارو اوږد قطار د لمر وړانګې فوکل ټکي ته منعکسوي. هلته د قطار په اوږدو کې د تېلو ډک پایپ وي او متمرکزې وړانګې تېل ګرموي. په لمریز حرارتي برېښناکوټ کې د ډېرو قطارونو تودوخه بخار جوړوي او بخار له جنراتور سره تړلی توربین چلوي.'),s('POINT TO PONDER: How automobile headlights produce a beam of light? Another application of parabolic mirrors is in automobile headlights. In a headlight, a high-intensity light source is placed at the focal point of the mirror, and light emerges parallel to the principal axis.','غوروفکر: گاڑی کی ہیڈلائٹس روشنی کی شعاع کیسے بناتی ہیں؟ قطعِ مکافی آئینے گاڑیوں کی ہیڈلائٹس میں بھی استعمال ہوتے ہیں۔ ہیڈلائٹ میں زیادہ شدت کا منبع آئینے کے مرکزی نقطے پر رکھا جاتا ہے اور روشنی محورِ اصلی کے متوازی نکلتی ہے۔','د فکر ټکی: د موټر څراغونه د رڼا وړانګه څنګه جوړوي؟ پارابولي هندارې د موټر په څراغونو کې هم کارېږي. پیاوړې رڼا د هندارې په فوکل ټکي کې اېښودل کېږي او رڼا د اصلي محور موازي وځي.'),
    s('12.3 THE MIRROR EQUATION: Drawing light ray diagrams are helpful in explaining and predicting the properties of images formed in plane, concave, and convex mirrors. To determine the magnification of the image, and its position with precision, it is necessary to draw very accurate scaled diagrams. The mirror equation, on the other hand, is a precise mathematical relationship between the object distance and the image distance for a given mirror. The following quantities are included in mirror formula: f = focal length of the mirror; hₒ = height of the object; hᵢ = height of the image; dₒ = distance of the object from the mirror; dᵢ = distance of the image from the mirror; M = magnification of the image.','12.3 آئینے کی مساوات: شعاعی خاکے ہموار، مقعر اور محدب آئینوں سے بننے والی تصاویر کی خصوصیات سمجھانے اور پیش گوئی کرنے میں مدد دیتے ہیں۔ تصویر کی بڑا نمائی اور مقام درست معلوم کرنے کے لیے پیمانے والے درست خاکے درکار ہیں۔ آئینے کی مساوات کسی آئینے کے لیے شے اور تصویر کے فاصلے کا دقیق ریاضیاتی تعلق ہے۔ علامات: f آئینے کا مرکزی فاصلہ؛ hₒ شے کی اونچائی؛ hᵢ تصویر کی اونچائی؛ dₒ آئینے سے شے کا فاصلہ؛ dᵢ آئینے سے تصویر کا فاصلہ؛ M تصویر کی بڑا نمائی۔','12.3 د هندارې معادله: د وړانګو انځورونه د هوارو، مقعرو او محدبو هندارو د انځور ځانګړنې تشریح او اټکل کوي. د غټوالي او ځای د دقیق موندلو لپاره کره پیمانه‌لرونکی رسم پکار دی. د هندارې معادله د ټاکلې هندارې لپاره د شي او انځور واټنونو دقیق ریاضيکي تړاو دی. نښې: f فوکل واټن؛ hₒ د شي لوړوالی؛ hᵢ د انځور لوړوالی؛ dₒ له هندارې د شي واټن؛ dᵢ د انځور واټن؛ M د انځور غټوالی.','heading'),
    s('To obtain this relation, we use the ray diagrams shown in Figure 12.9. The ray in Figure 12.9(a) hits the mirror at its pole, where the principal axis is the normal to the mirror. As a result, the ray reflects at an angle θᵢ below the principal axis equal to its incident angle θᵢ above the axis. The two green triangles in this diagram are similar, so ratios of equivalent sides are equal.','د یہ تعلق حاصل کرنے کے لیے شکل 12.9 کے شعاعی خاکے استعمال کرتے ہیں۔ شکل 12.9(a) میں شعاع قطب پر آئینے سے ٹکراتی ہے جہاں محورِ اصلی آئینے کا عمود ہے۔ چنانچہ شعاع محور کے اوپر وارد زاویہ θᵢ کے برابر زاویے سے محور کے نیچے منعکس ہوتی ہے۔ دونوں سبز مثلث متشابہ ہیں، لہٰذا متناظر اضلاع کے تناسب برابر ہیں۔','د دې اړیکې لپاره د 12.9 شکل د وړانګو انځورونه کاروو. په (a) کې وړانګه پر قطب لګېږي، چې اصلي محور هندارې ته عمود دی. نو وړانګه د محور لاندې د انعکاس په θᵢ زاویه ځي، چې د محور پورته د ورود زاویې سره برابره ده. دواړه شنې مثلثونه متشابه دي او د اړوندو ضلعو نسبتونه برابر دي.'),
    s('From Figure 12.9(a), hₒ / (−hᵢ) = dₒ / dᵢ (1). The image height is negative because it is inverted. From Figure 12.9(b), the two yellow triangles are similar and share angle φ; hence hₒ / (−hᵢ) = (dₒ − f) / f (2). Comparing equations (1) and (2), dₒ / dᵢ = (dₒ − f) / f. Cross-multiplying: dₒf = dᵢ(dₒ − f), or dₒf = dᵢdₒ − dᵢf (3). Dividing both sides by dₒdᵢf gives 1/dᵢ = 1/f − 1/dₒ; hence 1/f = 1/dᵢ + 1/dₒ (12.4).','شکل 12.9(a) سے hₒ/(−hᵢ) = dₒ/dᵢ (1)۔ تصویر الٹی ہونے کے باعث hᵢ منفی ہے۔ شکل 12.9(b) کے دو زرد مثلث متشابہ ہیں اور زاویہ φ مشترک ہے؛ لہٰذا hₒ/(−hᵢ) = (dₒ−f)/f (2)۔ مساوات (1) اور (2) کا موازنہ: dₒ/dᵢ = (dₒ−f)/f۔ طرفین ضرب دینے پر dₒf = dᵢ(dₒ−f)، یعنی dₒf = dᵢdₒ−dᵢf (3)۔ دونوں طرف dₒdᵢf سے تقسیم کرنے پر 1/dᵢ = 1/f−1/dₒ؛ لہٰذا 1/f = 1/dᵢ + 1/dₒ (12.4)۔','له 12.9(a) شکل څخه hₒ/(−hᵢ)=dₒ/dᵢ (1). د سرچپه انځور له امله hᵢ منفي دی. په (b) کې دوه ژېړ مثلثونه متشابه او φ زاویه شریکه لري؛ نو hₒ/(−hᵢ)=(dₒ−f)/f (2). د (1) او (2) پرتله: dₒ/dᵢ=(dₒ−f)/f. ضرب: dₒf=dᵢ(dₒ−f)، یعنې dₒf=dᵢdₒ−dᵢf (3). پر dₒdᵢf وېشلو سره 1/dᵢ=1/f−1/dₒ؛ نو 1/f=1/dᵢ+1/dₒ (12.4).'),
    s('Equation 12.4 is known as the mirror formula. It relates the distances of the object and the image to a concave mirror in terms of the mirror’s focal length. The ratio of the height of the image to the height of the object is defined as magnification, M; that is M = hᵢ/hₒ = −dᵢ/dₒ (12.5).','مساوات 12.4 آئینے کا فارمولا کہلاتی ہے۔ یہ مقعر آئینے کے لیے شے اور تصویر کے فاصلے کو مرکزی فاصلے سے مربوط کرتی ہے۔ تصویر کی اونچائی اور شے کی اونچائی کا تناسب بڑا نمائی M ہے: M = hᵢ/hₒ = −dᵢ/dₒ (12.5)۔','12.4 معادله د هندارې فورمول دی. د مقعرې هندارې لپاره د شي او انځور واټنونه د فوکل واټن سره تړي. د انځور او شي د لوړوالي نسبت غټوالی M دی: M=hᵢ/hₒ=−dᵢ/dₒ (12.5).'),
    s('12.3.1 Convention for mirror equation and magnification equation: To include all possible properties of both images and objects, the following sign convention has been established for both concave and convex spherical mirrors. a. Object distance: dₒ is positive for objects in front of the mirror (real objects). b. Image distance: dᵢ is positive for objects in front of the mirror (real images); dᵢ is negative for objects behind the mirror (virtual images). c. Image attitude: hᵢ is positive for images that are upright compared to the object; hᵢ is negative for images that are inverted compared to the object. d. Focal length: f is positive for concave mirrors; f is negative for convex mirrors.','12.3.1 آئینے کی مساوات اور بڑا نمائی کی علامتوں کا اصول: مقعر اور محدب کروی آئینوں میں اشیا اور تصاویر کی تمام ممکنہ خصوصیات کے لیے یہ علامتی اصول ہے۔ a. شے کا فاصلہ: آئینے کے سامنے حقیقی شے کے لیے dₒ مثبت۔ b. تصویر کا فاصلہ: آئینے کے سامنے حقیقی تصویر کے لیے dᵢ مثبت؛ آئینے کے پیچھے مجازی تصویر کے لیے منفی۔ c. تصویر کی وضع: شے کے مقابلے میں سیدھی تصویر کے لیے hᵢ مثبت؛ الٹی تصویر کے لیے منفی۔ d. مرکزی فاصلہ: مقعر آئینے کے لیے f مثبت؛ محدب کے لیے منفی۔','12.3.1 د هندارې معادلې او غټوالي نښې: د مقعرو او محدبو هندارو د شي او انځور د ځانګړنو لپاره دا نښې کارېږي. a. د شي واټن: د هندارې مخې ته د حقیقي شي لپاره dₒ مثبت. b. د انځور واټن: د مخې حقیقي انځور لپاره dᵢ مثبت؛ د شا مجازي انځور لپاره منفي. c. د انځور حالت: د سم انځور لپاره hᵢ مثبت؛ د سرچپه لپاره منفي. d. فوکل واټن: د مقعرې هندارې f مثبت او د محدبې f منفي دی.','heading'),
    s('Figure 12.10 - Mirror comparison: (a) Plane mirror image (no magnification). (b) Enlarged image in a concave mirror. (c) Reduced image in a convex mirror.','شکل 12.10 — آئینوں کا موازنہ: (a) ہموار آئینے میں تصویر (بڑا نمائی نہیں)۔ (b) مقعر آئینے میں بڑی تصویر۔ (c) محدب آئینے میں چھوٹی تصویر۔','12.10 شکل — د هندارو پرتله: (a) په هواره هنداره کې انځور (غټوالی نه لري). (b) په مقعره هنداره کې لوی انځور. (c) په محدبه هنداره کې کوچنی انځور.')
  ];
