 const coil='<svg viewBox="0 0 520 250" role="img" aria-label="Magnetic field around a coil and solenoid"><ellipse cx="135" cy="120" rx="85" ry="75" fill="none" stroke="#2563eb" stroke-width="3"/><ellipse cx="135" cy="120" rx="60" ry="52" fill="none" stroke="#2563eb" stroke-width="3"/><circle cx="135" cy="120" r="29" fill="#e2e8f0" stroke="#334155" stroke-width="3"/><path d="M90 35v170m20-170v170m20-170v170m20-170v170m20-170v170" stroke="#b45309" stroke-width="4"/><rect x="300" y="70" width="170" height="100" rx="14" fill="#bfdbfe" stroke="#334155" stroke-width="3"/><path d="M315 70q10 25 0 50t0 50m20-100q10 25 0 50t0 50m20-100q10 25 0 50t0 50m20-100q10 25 0 50t0 50m20-100q10 25 0 50t0 50m20-100q10 25 0 50t0 50" fill="none" stroke="#b45309" stroke-width="4"/><path d="M300 55h170M300 185h170" stroke="#2563eb" stroke-width="2"/><text x="135" y="230" text-anchor="middle">current loop</text><text x="385" y="230" text-anchor="middle">solenoid N ← axis → S</text></svg>';
 t.sourceFigures=t.sourceFigures||[];t.sourceFigures.push({id:'phys10-p5-17-compass',title:'Coded current-wire compass demonstration',svg:compass},{id:'phys10-p5-18-wire-field',title:'Coded concentric field of straight wire',svg:wire},{id:'phys10-p5-19-20-coil-fields',title:'Coded coil and solenoid magnetic fields',svg:coil});
