 force.sourcePages=force.sourcePages||[];force.sourcePages.push(
 {pdf:'10thphysics5.pdf',pdfPage:22,printedPage:'175',title:'Force on a current-carrying conductor',text:'Charges moving in a wire interact with external magnetic field and cause force. Force is perpendicular to current I and field B; reversing current reverses force. Force is greatest at 90° and zero when current is parallel to field.'},
 {pdf:'10thphysics5.pdf',pdfPage:23,printedPage:'176',title:'Magnetic force magnitude and tesla',text:'F_B∝BIL sinθ; F_B=kBIL sinθ, and in SI k=1: F_B=BIL sinθ (15.1). At θ=90°, F_B=BIL (15.2), and B=F_B/(IL). Tesla: 1 T=1 N/(1 A×1 m). Table 15.1 lists approximate fields: neutron star 10⁸ T; large electromagnet 1.5 T; small bar magnet 10⁻² T; Earth surface 10⁻⁴ T; interstellar space 10⁻¹⁰ T; magnetically shielded room 10⁻¹⁴ T. Fleming’s left-hand/right-hand rule III determines direction.'},
 {pdf:'10thphysics5.pdf',pdfPage:24,printedPage:'177',title:'Right-hand rule III and Fleming rule',text:'Right-hand rule III: right-hand fingers point along conventional current, bend toward magnetic field, thumb gives force; use left hand for electron flow. Fleming’s left hand: first finger field, second finger current, thumb force. Dot denotes vector out of page; cross denotes into page.'});
 force.summary.en+=' A current-carrying wire in an external magnetic field experiences force because moving charges interact with the field. Force is perpendicular to current and field; reversing current reverses force. F_B∝BIL sinθ and in SI F_B=BIL sinθ (15.1); it is maximum at 90°: F_B=BIL (15.2), so B=F_B/(IL). Tesla: 1 T=1 N/(1 A×1 m). Table 15.1: neutron star 10⁸ T; large electromagnet 1.5 T; small bar magnet 10⁻² T; Earth surface 10⁻⁴ T; interstellar space 10⁻¹⁰ T; shielded room 10⁻¹⁴ T. Right-hand rule III: fingers along conventional current, curl toward B, thumb gives force; use left hand for electron flow. Fleming’s left hand uses first finger B, second current, thumb force. Dot means out of page; cross means into page.';
 force.summary.ur+=' رو بردار تار بیرونی مقناطیسی میدان میں قوت محسوس کرتی ہے کیونکہ حرکت کرتے چارج میدان سے تعامل کرتے ہیں۔ قوت رو اور میدان دونوں پر عمود ہے؛ رو پلٹنے سے قوت پلٹتی ہے۔ F_B∝BIL sinθ اور SI میں F_B=BIL sinθ (15.1)؛ 90° پر زیادہ سے زیادہ F_B=BIL (15.2)، اس لیے B=F_B/(IL)۔ ٹیسلا: 1 T=1 N/(1 A×1 m)۔ جدول 15.1: نیوٹران ستارہ 10⁸ T؛ بڑا برقی مقناطیس 1.5 T؛ چھوٹا سلاخ مقناطیس 10⁻³ T؛ زمین کی سطح 10⁻⁴ T؛ بین النجمی خلا 10⁻¹⁰ T؛ مقناطیسی ڈھال والا کمرہ 10⁻¹⁴ T۔ دائیں ہاتھ کا قاعدہ III: انگلیاں روایتی رو کی سمت، موڑ میدان B کی طرف، انگوٹھا قوت بتاتا ہے؛ الیکٹران کے لیے بایاں ہاتھ۔ فلیمنگ بایاں ہاتھ: پہلی انگلی میدان، دوسری رو، انگوٹھا قوت؛ نقطہ صفحے سے باہر، کراس اندر کی سمت ہے۔';
 force.summary.ps+=' د جریان لرونکی تار په بهرني مقناطیسي میدان کې قوه تجربه کوي ځکه خوځنده چارجونه له میدان سره تعامل کوي. قوه پر جریان او میدان دواړو عموده ده؛ د جریان په اړولو قوه اړوي. F_B∝BIL sinθ او په SI کې F_B=BIL sinθ (15.1)؛ په 90° کې تر ټولو لوی F_B=BIL (15.2)، نو B=F_B/(IL). ټېسلا: 1 T=1 N/(1 A×1 m). 15.1 جدول: نیوترون ستوری 10⁸ T؛ لوی برېښنايي مقناطیس 1.5 T؛ کوچنی میله‌يي مقناطیس 10⁻³ T؛ د ځمکې سطحه 10⁻⁴ T؛ بین‌ستوري فضا 10⁻¹⁰ T؛ مقناطیسي خوندي خونه 10⁻¹⁴ T. د ښي لاس قاعده III: ګوتې د قراردادي جریان پر لوري، تاو یې د B پر لوري، غټه ګوته قوه ښيي؛ د الکتروني جریان لپاره چپ لاس. د فلېمنګ چپ لاس: لومړۍ ګوته میدان، دویمه جریان، غټه ګوته قوه؛ ټکی د پاڼې له مخې بهر او صلیب د پاڼې دننه لوری دی.';
 const forceFig='<svg viewBox="0 0 500 250" role="img" aria-label="Force on current carrying conductor in a magnetic field"><rect x="80" y="45" width="90" height="130" fill="#2563eb"/><rect x="330" y="45" width="90" height="130" fill="#16a34a"/><text x="125" y="115" text-anchor="middle" fill="white" font-size="26">N</text><text x="375" y="115" text-anchor="middle" fill="white" font-size="26">S</text><path d="M190 110h120" stroke="#b45309" stroke-width="8"/><path d="M290 98l20 12-20 12" fill="#b45309"/><path d="M250 100V20" stroke="#b91c1c" stroke-width="5"/><path d="M238 35l12-18 12 18" fill="#b91c1c"/><text x="255" y="15">F</text><text x="245" y="145">I</text><path d="M195 200h110" stroke="#2563eb" stroke-width="3"/><text x="240" y="225">B: N to S</text></svg>';
