 gate.sourcePages=gate.sourcePages||[];gate.sourcePages.push(
 {pdf:'10thphysics6.pdf',pdfPage:17,printedPage:'210',title:'Unit 16 key points and projects',text:'Key points define thermionic emission as temperature-induced electron ejection; an electron gun as a source of focused, accelerated cathode-ray beam; CRO as an electron gun, deflecting plates and fluorescent screen in an evacuated chamber; analogue quantities as continuous and digital quantities as discrete symbols (0/1); logic gates, Boolean equations and truth tables. Group projects: automatic water pump using roof-tank and well-water conditions; automatic front-gate lighting using sensors and gates; classroom chart of NOT, OR, AND, NOR and NAND symbols/truth tables. Page also states a NOR output/alarm is high when both tank sensor outputs are low and a NAND circuit can indicate both tanks full.'},
 {pdf:'10thphysics6.pdf',pdfPage:18,printedPage:'211',title:'Unit 16 group projects and multiple-choice exercise',text:'Projects include researching why CRT television screens were replaced by LED/LCD and remaining CRT research; and an essay on digital electronics, examples of the shift from low-tech appliances to high-tech ones, and computers at the forefront. MCQs: (1) cathode rays are a beam of protons/electrons/ions/neutrons; (2) electric field parallel to electron beam: speed up/slow down/deflect/no change; (3) magnetic field parallel: speed up/slow down/deflect/no change; (4) output high only when all inputs high: AND/OR/NAND/NOR; (5) output high when one or more inputs high: AND/OR/NAND/NOR; (6) output low when all inputs high: AND/OR/NAND/NOR; (7) output low when one or more inputs high: AND/OR/NAND/NOR; (8) Boolean equation for OR; (9) Boolean equation for NAND.'},
 {pdf:'10thphysics6.pdf',pdfPage:19,printedPage:'212',title:'Unit 16 conceptual and comprehensive questions',text:'Conceptual questions ask about free electrons, accelerating-anode function, how a scanning TV beam makes a full picture, magnetic distortion of CRT images, demonstrating cathode-ray negative charge, combinations for a four-input gate, high-output conditions for AND and NOR, and Boolean expressions for AND/OR/NOT/NAND/NOR. Comprehensive questions ask about thermionic emission, cathode rays, electron-gun construction/operation, electric/magnetic deflection, CRO principle/uses, analogue vs digital electronics, gate definitions/symbols/truth tables, and gate applications in automatic lights and textile coloring.'});
 gate.summary.en+=' Unit projects apply gates to a water pump, front-gate lighting, tank alarms and classroom truth-table charts. Review questions cover cathode rays, electron-beam deflection, Boolean expressions, gate truth tables, CROs and analogue/digital electronics.';
 gate.summary.ur+=' اس اکائی کے منصوبوں میں پانی کے پمپ، گھر کے گیٹ کی روشنی، ٹینک الارم اور جماعت میں truth table چارٹ کے لیے گیٹس استعمال کیے جاتے ہیں۔ سوالات میں کیتھوڈ شعاعیں، بیم کا انحراف، Boolean expressions، گیٹ truth tables، CRO اور اینالاگ/ڈیجیٹل الیکٹرانکس شامل ہیں۔';
 gate.summary.ps+=' د دې څپرکي پروژې د اوبو پمپ، د کور د دروازې څراغ، د ټانک الارم او د ټولګي د حقیقت‌جدول چارټ لپاره منطقي دروازې کاروي. پوښتنې د کاتودي وړانګو، د بیم انحراف، Boolean څرګندونو، د دروازو حقیقت‌جدولونو، CRO او انالوګ/ډیجیټلي الکترونیک په اړه دي.';
