function renderPhysics10SourceParagraph(p, id, field = 'text') {
  const prose = p[field];
  if (!p.formulas && !p.lead) return field === 'text' ? renderInteractiveParagraphHtml(prose, p.urdu, p.pashto, id, true) : sanitize(prose);
  let inner = '';
  let offset = 0;
  if (p.lead && prose.startsWith(p.lead[field])) {
    inner += `<strong>${sanitize(p.lead[field])}</strong>`;
    offset = p.lead[field].length;
  }
  for (const formula of p.formulas || []) {
    const start = prose.indexOf(formula.source, offset);
    if (start < 0) continue;
    inner += sanitize(prose.slice(offset, start));
    inner += typeof katex !== 'undefined' ? katex.renderToString(formula.latex, {throwOnError: false}) : formula.mathml;
    offset = start + formula.source.length;
  }
  inner += sanitize(prose.slice(offset));
  return field === 'text' ? `<span class="lesson-sentence" data-para="${id}" data-sent="0" data-en="${sanitize(p.text)}" data-ur="${sanitize(p.urdu)}" data-ps="${sanitize(p.pashto)}" onmouseenter="highlightSentence(this)" onmouseleave="unhighlightSentence(this)" onclick="toggleSentenceTranslation(this, event)">${inner}</span>` : inner;
}

function physics10SpringPath(start,end,y,turns,amplitude) {
  const step=(end-start)/(turns*2);
  return `M${start} ${y} `+Array.from({length:turns*2},(_,i)=>`L${start+(i+1)*step} ${y+(i%2?amplitude:-amplitude)}`).join(' ')+` L${end+5} ${y}`;
}

